function b({registerIndicator:p,sourceValues:h,nulls:d}){p({id:"oa-holt",name:"Holt Exponential Moving Average (HOLT)",category:"Trends IIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"gamma",type:"number",label:"Gamma (0 = auto)",default:0,min:0,max:1,step:.01,tooltip:"Trend smoothing factor. Left at 0 it matches alpha, which is 2 / (period + 1)."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"holt",type:"line",title:"HOLT",style:{color:"#ffeb3b",lineWidth:2}}],calc(l,n){const f=Math.max(1,Math.floor(Number(n.period)||10)),m=Number(n.gamma),c=Number.isFinite(m)?Math.min(1,Math.max(0,m)):0,y=h(l,n.source??"close"),i=2/(f+1),s=c>0?c:i,r=new Array(l.length).fill(NaN);let e=NaN,t=0;for(let o=0;o<l.length;o++){const a=y[o];if(!Number.isFinite(a))continue;if(!Number.isFinite(e)){e=a,t=0,r[o]=a;continue}const u=e;e=i*a+(1-i)*(u+t),t=s*(e-u)+(1-s)*t,r[o]=e+t}return{holt:d(r)}}})}export{b as default};
